@IsTest private class CacheExceptionObservation62 { @IsTest static void observe(){
Map<String,Object> result = new Map<String,Object>();
Cache.CacheException value = new Cache.CacheException('owned cache message');
result.put('directMessage', value.getMessage());
result.put('type', value.getTypeName());
try { throw value; } catch (Cache.CacheException caught) { result.put('caughtMessage', caught.getMessage()); }
value.setMessage('changed cache message');
result.put('setMessage', value.getMessage());
result.put('defaultMessage', new Cache.CacheException().getMessage());
IllegalArgumentException control = new IllegalArgumentException('owned standard message');
result.put('controlDirect', control.getMessage());
try { throw control; } catch (Exception caught) { result.put('controlCaught', caught.getMessage()); }
System.assertEquals('CACHE_EXCEPTION_OBSERVATION',JSON.serialize(result),'CACHE_EXCEPTION_OBSERVATION');
} }

